    h += n === '…' ? '<span class="pgdots">…</span>' : '<button class="pgbtn' + (n === cur ? ' on' : '') + '" data-kind="' + kind + '" data-p="' + n + '" onclick="setPageEl(this)">' + faN(n) + '</button>';
