  var head = d.slice(0, 4), tail = d.slice(-3);
  var n = Math.min(8, Math.max(3, d.length - head.length - tail.length)), stars = '';
  for (var i = 0; i < n; i++) stars += '*';
  return '+' + head + stars + tail;
